def read_lines(filename):
    for line in ["10,30", "20,INVALID", "15,45"]:
        yield line

def parse_nums(lines):
    for line in lines:
        parts = line.split(',')
        if parts[1].isdigit():
            yield int(parts[0]) + int(parts[1])

# Processing pipeline
pipeline = parse_nums(read_lines("data.txt"))
print(list(pipeline))  # [40, 60]
